  "returncode": 0,
  "output_head": "//! The route table from Rails Campfire's `config/routes.rb` (plus the framework routes
//! `bin/rails routes` lists: Active Storage, Turbo Native navigation, Action Mailbox, `/up`), and
//! a router that matches the way Rails' Journey does.
//!
//! Axum only sees one catch-all route; [`dispatch`] then picks the *first* route in table order
//! whose verb and pattern match, exactly as Rails does. That matters: `GET /rooms/opens` is
//! `rooms#show` with `id: "opens"` because `resources :rooms` is drawn before
//! `namespace :rooms`. Patterns use Rails syntax: `:param` matches `[^/.?]+`, `*glob` matches
//! lazily, and `(.:format)` is the optional format suffix (so `/rooms/1.json` sets
//! `params[:format]`). Path params are percent-decoded and merged over query and body params,
//! together with `controller` and `action`.
//!
//! ## Adding a controller
//!
//! Add `pub mod rooms;` (etc.) below, write `pub async fn show(c: &mut Ctx) -> Result` actions that
//! start with their before-action chain (see `crate::concerns`), and put `rooms::show` in the
//! matching rows. Declared routes whose action Rails doesn't define (e.g. `first_runs#edit`) answer
//! 404 like `AbstractController::ActionNotFound`: map them to `action_not_found`. Never reorder,
//! add or remove rows: the table must stay identical to `bin/rails routes` (checked by the tests
//! below against `vectors/campfire_routes.json`, recorded from Rails).

use std::sync::{Arc, LazyLock};

use campfire_kit::{Ctx, Error, Method, Param, ParamMap, Result, StatusCode};
use futures_util::future::BoxFuture;
use regex::{Regex, RegexSet};

use crate::active_storage;

// Controller modules (one per Rails controller namespace), plus the presenters that map rows to
// view models. Controller agents add their `pub mod` lines here.
pub mod accounts;
pub mod autocompletable;
pub mod first_runs;
pub mod messages;
pub mod presenters;
pub mod pwa;
pub mod qr_code;
pub mod rooms;
pub mod searches;
pub mod sessions;
pub mod unfurl_links;
pub mod users;
pub mod welcome;

/// Anything that can serve a route: every `async fn(&mut Ctx) -> Result` qualifies.
pub trait Action: Send + Sync + 'static {
    fn call<'a>(&'a self, c: &'a mut Ctx) -> BoxFuture<'a, Result>;
}

impl<F> Action for F
where
    F: for<'a> campfire_kit::ActionFn<'a>,
{
    fn call<'a>(&'a self, c: &'a mut Ctx) -> BoxFuture<'a, Result> {
        Box::pin(campfire_kit::ActionFn::call(self, c))
    }
}

pub struct Route {
    pub verb: Method,
    /// The Rails path spec, e.g. `/rooms/:room_id/messages(.:format)`. Compiled into `regex`; kept
    /// for the test that compares the table with `bin/rails routes`.
    #[cfg_attr(not(test), allow(dead_code))]
    pub pattern: &'static str,
    /// `controller#action`, as `bin/rails routes` prints it.
    pub endpoint: &'static str,
    pub defaults: &'static [(&'static str, &'static str)],
    action: Arc<dyn Action>,
    regex: Regex,
    names: Vec<String>,
}

impl Route {
    fn new(verb: Method, pattern: &'static str, endpoint: &'static str, action: impl Action) -> Self {
        let (regex, names) = compile(pattern);
        Self { verb, pattern, endpoint, defaults: &[], action: Arc::new(action), regex, names }
    }

    fn defaults(mut self, defaults: &'static [(&'static str, &'static str)]) -> Self {
        self.defaults = defaults;
