impl Session {
    pub fn find(conn: &Connection, id: i64) -> Result<Self> {
        query_one(
            conn,
            concat!("SELECT ", session_columns!(), r#" FROM "sessions" WHERE "sessions"."id" = ? LIMIT 1"#),
            [id],
