    }

    pub fn for_user(conn: &Connection, user_id: i64) -> Result<Vec<Self>> {
        query_all(
            conn,
            concat!("SELECT ", session_columns!(), r#" FROM "sessions" WHERE "sessions"."user_id" = ?"#),
            [user_id],
            Self::from_row,
