    /// `db.write` for actions, whose errors become responses as [`db_error`] maps them.
    pub async fn write<T, F>(&self, f: F) -> campfire_kit::Result<T>
    where
        T: Send + 'static,
        F: FnOnce(&mut Tx<'_>) -> campfire_db::Result<T> + Send + 'static,
    {
