pub fn attachment_gallery_nodes(dom: &Dom, root: NodeId) -> Vec<NodeId> {
    dom.descendants(root)
        .into_iter()
        .filter(|&div| dom.local_name(div) == Some("div"))
        .filter(|&div| {
            dom.descendants(div).into_iter().any(|n| {
