const EDGE: &[&str] = &["Edg"];

/// `user_agent.browser.match?(/A|B/)`, which raises for a nil browser.
fn browser_matches(browser: &Rb<Option<String>>, names: &[&str]) -> Rb<bool> {
    let browser = browser.as_ref().map_err(|_| Raised)?.as_deref().ok_or(Raised)?;
